// Generated by scripts/sync-draw-blocks.mjs from Draw. Edit the production source, then sync.
import { blockType, isBadge } from './blocks'
import { fontFamily } from './text'
import type { Shape } from './types'

// Measurements from the Learn designer's node cards (rete-diagram.css).
const radius = 12
const header = 32
const titleSize = 18
const subtitleSize = 13
const badgeSize = 28
const badgeGap = 8
const logoSize = 40

export function BlockShadow({ idPrefix = '' }: { idPrefix?: string }) {
  return (
    <filter id={`${idPrefix}block-shadow`} x="-20%" y="-20%" width="140%" height="160%">
      <feDropShadow className="block-shadow" dx="0" dy="6" stdDeviation="8" />
    </filter>
  )
}

/**
 * A building block: a white (or, in dark mode, dark) card with a coloured header, then its type's logo
 * (cloud services show their provider's icon), the title and subtitle, and the
 * platform badges, centred in the space below the header. Labels and badges
 * are the shape's own, so templates can name blocks ("Agent 2"); the header
 * and title fall back to the block type's. A block resized too small for
 * everything drops its badges, then its subtitle, then its logo; what remains
 * is clipped to the card so it never spills over.
 */
export function BlockView({ shape: s, idPrefix = '' }: { shape: Shape; idPrefix?: string }) {
  const type = blockType(s.block)
  if (type.icon) {
    // Scaled to fit its box without distortion; the transparent rect keeps
    // the empty corners around the icon grabbable.
    return (
      <g data-id={s.id} className="block">
        <rect x={s.x} y={s.y} width={s.w} height={s.h} fill="transparent" />
        <svg
          x={s.x}
          y={s.y}
          width={s.w}
          height={s.h}
          viewBox={type.icon.viewBox}
          preserveAspectRatio="xMidYMid meet"
          strokeLinejoin="round"
          overflow="visible"
          dangerouslySetInnerHTML={{ __html: type.icon.markup }}
        />
      </g>
    )
  }
  const headerText = s.header || type.header
  const title = s.title || type.title
  const subtitle = s.subtitle ?? ''
  const cx = s.x + s.w / 2
  const room = s.h - header - 12
  // What fits, in order of importance: title, logo, subtitle, badges.
  const titleHeight = titleSize * 1.2
  const logoHeight = type.logo && titleHeight + logoSize + 8 <= room ? logoSize + 8 : 0
  const fullSubtitleHeight = 4 + subtitleSize * 1.2
  const subtitleHeight = subtitle && logoHeight + titleHeight + fullSubtitleHeight <= room ? fullSubtitleHeight : 0
  const allBadges = (s.badges ?? []).filter(isBadge)
  const fullBadgesWidth = allBadges.length * badgeSize + (allBadges.length - 1) * badgeGap
  const badgesFit = logoHeight + titleHeight + subtitleHeight + 8 + badgeSize <= room && fullBadgesWidth <= s.w - 16
  const badges = badgesFit ? allBadges : []
  const badgesHeight = badges.length ? 8 + badgeSize : 0
  const badgesWidth = badgesFit ? fullBadgesWidth : 0
  const top = s.y + header + Math.max(0, (s.h - header - logoHeight - titleHeight - subtitleHeight - badgesHeight) / 2)
  const textTop = top + logoHeight
  const clip = `${idPrefix}block-clip-${s.id}`

  // Card, title and subtitle colours are the stylesheet's, so dark mode can darken them.
  return (
    <g data-id={s.id} className="block">
      <clipPath id={clip}>
        <rect x={s.x} y={s.y} width={s.w} height={s.h} rx={radius} />
      </clipPath>
      <rect
        x={s.x}
        y={s.y}
        width={s.w}
        height={s.h}
        rx={radius}
        className="block-card"
        filter={`url(#${idPrefix}block-shadow)`}
      />
      <g clipPath={`url(#${clip})`} fontFamily={fontFamily} textAnchor="middle">
        <rect x={s.x} y={s.y} width={s.w} height={header} fill={type.color} />
        <text x={cx} y={s.y + header / 2} dominantBaseline="central" fontSize={12} fontWeight={700} letterSpacing="0.08em" fill="#ffffff">
          {headerText}
        </text>
        {logoHeight > 0 && <image href={type.logo} x={cx - logoSize / 2} y={top} width={logoSize} height={logoSize} />}
        <text x={cx} y={textTop + titleSize} fontSize={titleSize} fontWeight={700} className="block-title">
          {title}
        </text>
        {subtitleHeight > 0 && (
          <text x={cx} y={textTop + titleHeight + 4 + subtitleSize} fontSize={subtitleSize} className="block-subtitle">
            {subtitle}
          </text>
        )}
        {badges.map((badge, i) => (
          <image
            key={badge}
            href={`/draw-blocks/badges/${badge}.svg`}
            x={cx - badgesWidth / 2 + i * (badgeSize + badgeGap)}
            y={textTop + titleHeight + subtitleHeight + 8}
            width={badgeSize}
            height={badgeSize}
          />
        ))}
      </g>
    </g>
  )
}
